import type { ReactNode } from "react";
import { cn } from "./utils";

export type AttachmentItemProps = {
    name: string;
    size?: number;
    status?: string;
    preview?: ReactNode;
    actions?: ReactNode;
    error?: string;
    className?: string;
};

export function formatFileSize(bytes: number): string {
    if (!Number.isFinite(bytes) || bytes < 0) throw new RangeError("File size must be finite and nonnegative.");
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

export function AttachmentItem({ name, size, status, preview, actions, error, className }: AttachmentItemProps) {
    if (!name.trim()) throw new Error("AttachmentItem requires a name.");
    return <div data-ui="attachment-item" className={cn("flex min-w-0 flex-wrap items-center gap-3 rounded-sm border border-border bg-surface px-3 py-2 text-sm text-foreground", className)}>
        {preview && <div className="size-10 shrink-0 overflow-hidden rounded-sm" aria-hidden="true">{preview}</div>}
        <div className="min-w-0 flex-1 basis-24">
            <span className="block [overflow-wrap:anywhere]">{name}</span>
            <span className="flex flex-wrap gap-x-2 text-xs text-muted">
                {size !== undefined && <span>{formatFileSize(size)}</span>}
                {status && <span>{status}</span>}
            </span>
        </div>
        {actions && <div className="flex flex-wrap items-center gap-2">{actions}</div>}
        {error && <p role="alert" className="m-0 basis-full text-xs text-danger">{error}</p>}
    </div>;
}
